(function(E){ const x = E["exam-02"] = E["exam-02"] || {units:{}}; (x.units = x.units || {})["x02-s"] = {"id":"x02-s","patterns":["S1-frame","S1-places","S2-experience","S3-consumer","S3-education","TR-short","PARA-discuss"],"title":{"en":"Speaking","tr":"Speaking","fa":"Speaking (صحبت کردن)"},"objective":{"en":"In this lesson you will learn to take the whole Speaking test: answer questions about your neighbourhood in two or three sentences, tell a two-minute story about advice that went wrong, and discuss honesty and online reviews with a view, a reason and an example.","tr":"Bu derste Speaking sınavının tamamını yapmayı öğreneceksin: mahallenle ilgili soruları iki üç cümleyle cevaplayacak, yanlış çıkan bir tavsiye hakkında iki dakikalık bir hikâye anlatacak, dürüstlük ve çevrim içi yorumları bir görüş, bir neden ve bir örnekle tartışacaksın.","fa":"در این درس یاد می‌گیری کل آزمون Speaking را انجام بدهی: به سؤال‌های مربوط به محله‌ات با دو سه جمله جواب بدهی، دو دقیقه داستان توصیه‌ای را که غلط از آب درآمد تعریف کنی و درباره‌ی صداقت و نظرهای آنلاین با یک نظر، یک دلیل و یک مثال بحث کنی."},"sessions":[["explain"],["sets"],["exit"]],"explain":{"title":{"en":"Speaking: Parts 1, 2 and 3","tr":"Speaking: Part 1, 2 ve 3","fa":"Speaking: بخش‌های ۱، ۲ و ۳"},"objective":{"en":"In this lesson you will learn to take the whole Speaking test: answer questions about your neighbourhood in two or three sentences, tell a two-minute story about advice that went wrong, and discuss honesty and online reviews with a view, a reason and an example.","tr":"Bu derste Speaking sınavının tamamını yapmayı öğreneceksin: mahallenle ilgili soruları iki üç cümleyle cevaplayacak, yanlış çıkan bir tavsiye hakkında iki dakikalık bir hikâye anlatacak, dürüstlük ve çevrim içi yorumları bir görüş, bir neden ve bir örnekle tartışacaksın.","fa":"در این درس یاد می‌گیری کل آزمون Speaking را انجام بدهی: به سؤال‌های مربوط به محله‌ات با دو سه جمله جواب بدهی، دو دقیقه داستان توصیه‌ای را که غلط از آب درآمد تعریف کنی و درباره‌ی صداقت و نظرهای آنلاین با یک نظر، یک دلیل و یک مثال بحث کنی."},"stats":[{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"11-14 min","tr":"11-14 dk","fa":"۱۱ تا ۱۴ دقیقه"}},{"label":{"en":"Parts","tr":"Kısım","fa":"بخش"},"value":"3"},{"label":{"en":"Part 2 talk","tr":"Part 2 konuşması","fa":"صحبت Part 2"},"value":{"en":"2 min","tr":"2 dk","fa":"۲ دقیقه"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: your area, bad advice, trust","tr":"Bu sınav: bölgen, kötü bir tavsiye, güven","fa":"این آزمون: محله‌ات، یک توصیه‌ی بد، اعتماد"},"intro":{"en":"The three parts are linked: Part 1 is about you, Part 2 is one experience on a card, and Part 3 widens the Part 2 topic to people and society. Here, advice that went wrong leads to questions about honesty and trust.","tr":"Üç kısım birbirine bağlıdır: Part 1 seninle ilgili, Part 2 karttaki bir deneyim ve Part 3, Part 2 konusunu insanlara ve topluma genişletir. Burada yanlış çıkan bir tavsiye, dürüstlük ve güvenle ilgili sorulara götürür.","fa":"سه بخش به هم وصل‌اند: Part 1 درباره‌ی خودت است، Part 2 یک تجربه روی کارت و Part 3 موضوع Part 2 را به آدم‌ها و جامعه گسترش می‌دهد. این‌جا توصیه‌ای که غلط از آب درآمد به سؤال‌هایی درباره‌ی صداقت و اعتماد می‌رسد."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x02-s1-ctx","exam":true,"patterns":["S1-frame","S1-places"],"often":{"pattern":"S1-places","n":8,"of":40,"label":{"en":"Comes up often in the real exam: 8 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 8’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۸ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Part 1: you, then your neighbourhood","tr":"Part 1: sen, sonra mahallen","fa":"Part 1: خودت، بعد محله‌ات"},"asks":{"en":"The examiner checks your name and asks about your work, studies or home, then four questions on one everyday topic. Here the topic is the area where you live.","tr":"Sınav görevlisi adını kontrol eder, işini, okulunu ya da evini sorar, sonra günlük bir konuda dört soru sorar. Burada konu yaşadığın bölge.","fa":"ممتحن اسمت را چک می‌کند، درباره‌ی کار، درس یا خانه‌ات می‌پرسد و بعد چهار سؤال درباره‌ی یک موضوع روزمره. این‌جا موضوع محله‌ای است که در آن زندگی می‌کنی."},"fields":["Work or studies","Home","Your neighbourhood","Neighbours","Changes","A place you like nearby"],"words":[{"a":"neighbourhood","b":"the area where I live / my part of town","tr":"mahalle","fa":"محله"},{"a":"quiet","b":"peaceful / not much traffic","tr":"sakin","fa":"آرام"},{"a":"lively","b":"busy / there’s always something going on","tr":"hareketli","fa":"شلوغ و پرجنب‌وجوش"},{"a":"convenient","b":"everything is close by","tr":"elverişli, her şey yakın","fa":"دم‌دست"},{"a":"neighbours","b":"the people who live next door","tr":"komşular","fa":"همسایه‌ها"},{"a":"get on well with","b":"have a good relationship with","tr":"iyi geçinmek","fa":"رابطه‌ی خوب داشتن"},{"a":"has changed a lot","b":"it’s very different now","tr":"çok değişti","fa":"خیلی عوض شده"},{"a":"a local café","b":"a café near my home","tr":"mahalledeki kafe","fa":"کافه‌ی محل"},{"a":"public transport","b":"buses, trams, the metro","tr":"toplu taşıma","fa":"حمل‌ونقل عمومی"},{"a":"to be honest","b":"actually / if I’m truthful","tr":"açıkçası","fa":"راستش"}],"traps":[{"en":"One-word answers: \"Yes, it’s nice.\" Add why and one detail: what makes it nice?","tr":"Tek kelimelik cevaplar: \"Yes, it’s nice.\" Nedenini ve bir ayrıntı ekle: onu güzel yapan ne?","fa":"جواب‌های یک‌کلمه‌ای: «Yes, it’s nice.». دلیل و یک جزئیات اضافه کن: چه چیزی خوبش می‌کند؟"},{"en":"Describing your whole city when the question is about your street or area. Answer the question you were asked.","tr":"Soru sokağın ya da bölgenle ilgiliyken bütün şehrini anlatmak. Sana sorulan soruyu cevapla.","fa":"وقتی سؤال درباره‌ی خیابان یا محله‌ات است، کل شهر را توصیف کردن. به همان سؤالی جواب بده که از تو پرسیده شده."}],"example":{"text":"Q: \"Is your neighbourhood a good place for children?\"","item":"Which answer is the right length?","answer":"Yes, I’d say so. There’s a big park two minutes away, and the streets are fairly quiet, so kids can play outside safely.","why":{"en":"An answer, then two concrete reasons: about ten seconds.","tr":"Bir cevap, sonra iki somut neden: yaklaşık on saniye.","fa":"یک جواب، بعد دو دلیل مشخص: حدود ده ثانیه."}}},{"id":"x02-s2-ctx","exam":true,"patterns":["S2-experience","PARA-discuss"],"often":{"pattern":"S2-experience","n":17,"of":40,"label":{"en":"Comes up often in the real exam: 17 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 17’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۷ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Part 2: advice that turned out to be wrong","tr":"Part 2: sonradan yanlış çıkan bir tavsiye","fa":"Part 2: توصیه‌ای که بعداً غلط از آب درآمد"},"asks":{"en":"You get a card about an experience: a time someone gave you advice that turned out to be wrong. One minute to prepare, then up to two minutes alone. Experiences are the most common Part 2 card.","tr":"Bir deneyim kartı alırsın: birinin sana sonradan yanlış çıkan bir tavsiye verdiği bir an. Bir dakika hazırlık, sonra iki dakikaya kadar tek başına konuşma. Deneyimler en sık çıkan Part 2 kartıdır.","fa":"کارتی درباره‌ی یک تجربه می‌گیری: وقتی کسی به تو توصیه‌ای کرد که بعداً غلط از آب درآمد. یک دقیقه آماده شدن، بعد تا دو دقیقه حرف زدن به‌تنهایی. تجربه‌ها رایج‌ترین کارت Part 2 هستند."},"fields":["Who gave the advice","What the advice was","What happened when you followed it","Why it was wrong","What you learned"],"words":[{"a":"advise someone to","b":"tell someone they should","tr":"birine ... yapmasını tavsiye etmek","fa":"به کسی توصیه کردن که"},{"a":"take someone’s advice","b":"do what they suggest","tr":"birinin tavsiyesine uymak","fa":"به توصیه‌ی کسی عمل کردن"},{"a":"it turned out that","b":"later I found out that","tr":"sonradan ortaya çıktı ki","fa":"بعداً معلوم شد که"},{"a":"meant well","b":"was trying to help","tr":"iyi niyetliydi","fa":"نیتش خیر بود"},{"a":"out of date","b":"no longer true","tr":"güncelliğini yitirmiş","fa":"قدیمی، دیگر درست نیست"},{"a":"regret","b":"wish I had not done it","tr":"pişman olmak","fa":"پشیمان شدن"},{"a":"in hindsight","b":"looking back","tr":"geriye bakınca","fa":"وقتی به گذشته نگاه می‌کنم"},{"a":"double-check","b":"check again for myself","tr":"iki kez kontrol etmek","fa":"دوباره چک کردن"},{"a":"it was a lesson for me","b":"I learned something from it","tr":"benim için bir ders oldu","fa":"برایم درس شد"},{"a":"at the time","b":"then, when it happened","tr":"o zaman","fa":"آن موقع"}],"traps":[{"en":"Stopping after one minute. The last line, \"and explain how you felt about it\", is where you develop the talk with reasons and reflection.","tr":"Bir dakikadan sonra durmak. Son satır, \"and explain how you felt about it\", konuşmayı nedenler ve düşüncelerle geliştirdiğin yerdir.","fa":"بعد از یک دقیقه ساکت شدن. خط آخر، «and explain how you felt about it»، جایی است که صحبت را با دلیل و فکر کردن به آن گسترش می‌دهی."},{"en":"Mixing tenses. Tell the story in the past: past simple for events, past continuous for the background.","tr":"Zamanları karıştırmak. Hikâyeyi geçmiş zamanla anlat: olaylar için past simple, arka plan için past continuous.","fa":"قاطی کردن زمان‌ها. داستان را در گذشته تعریف کن: گذشته‌ی ساده برای اتفاق‌ها، گذشته‌ی استمراری برای پس‌زمینه."}],"example":{"text":"Card line: \"what the advice was\"","item":"Which sentence answers it clearly?","answer":"My cousin told me I should buy my laptop online, because he said it would be much cheaper than in the shops.","why":{"en":"Who, what and the reason they gave, all in one sentence.","tr":"Kim, ne ve verdiği neden, hepsi tek cümlede.","fa":"چه کسی، چه چیزی و دلیلی که آورد، همه در یک جمله."}}},{"id":"x02-s3-ctx","exam":true,"patterns":["S3-consumer","S3-education","PARA-discuss","TR-short"],"often":{"pattern":"S3-consumer","n":8,"of":40,"label":{"en":"Comes up often in the real exam: 8 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 8’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۸ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Part 3: honesty, trust and online reviews","tr":"Part 3: dürüstlük, güven ve çevrim içi yorumlar","fa":"Part 3: صداقت، اعتماد و نظرهای آنلاین"},"asks":{"en":"The examiner asks six general questions linked to the Part 2 topic: how children learn to be honest, and whether we can trust advice and reviews online.","tr":"Sınav görevlisi Part 2 konusuyla bağlantılı altı genel soru sorar: çocuklar dürüst olmayı nasıl öğrenir ve internetteki tavsiyelere ve yorumlara güvenebilir miyiz.","fa":"ممتحن شش سؤال کلی مرتبط با موضوع Part 2 می‌پرسد: بچه‌ها چطور صادق بودن را یاد می‌گیرند و آیا می‌شود به توصیه‌ها و نظرهای اینترنتی اعتماد کرد."},"fields":["Learning honesty","Parents and teachers","White lies","Online reviews","Fake reviews","Who should check them"],"words":[{"a":"honest","b":"telling the truth","tr":"dürüst","fa":"صادق"},{"a":"a white lie","b":"a small lie to be kind","tr":"masum yalan","fa":"دروغ مصلحتی"},{"a":"set an example","b":"show children by doing it yourself","tr":"örnek olmak","fa":"الگو بودن"},{"a":"trust","b":"believe that someone is honest","tr":"güvenmek","fa":"اعتماد کردن"},{"a":"reliable","b":"you can depend on it","tr":"güvenilir","fa":"قابل‌اعتماد"},{"a":"a fake review","b":"a review written to trick buyers","tr":"sahte yorum","fa":"نظر جعلی"},{"a":"misleading","b":"giving the wrong idea","tr":"yanıltıcı","fa":"گمراه‌کننده"},{"a":"regulate","b":"control with rules or laws","tr":"düzenlemek, denetlemek","fa":"قانون‌گذاری و نظارت"},{"a":"on the whole","b":"in general / mostly","tr":"genel olarak","fa":"روی‌هم‌رفته"},{"a":"it depends on","b":"it varies according to","tr":"... bağlıdır","fa":"بستگی دارد به"}],"traps":[{"en":"A one-sentence opinion. Part 3 wants a view, a reason, an example and, when it helps, the other side.","tr":"Tek cümlelik bir görüş. Part 3 bir görüş, bir neden, bir örnek ve gerektiğinde karşı tarafı ister.","fa":"نظری در یک جمله. Part 3 یک نظر، یک دلیل، یک مثال و هرجا لازم بود طرف مقابل را می‌خواهد."},{"en":"Talking only about yourself. \"Why do people trust online reviews?\" is about people in general, not only your own shopping.","tr":"Yalnızca kendinden söz etmek. \"İnsanlar neden çevrim içi yorumlara güvenir?\" sorusu yalnızca senin alışverişinle değil, genel olarak insanlarla ilgilidir.","fa":"فقط از خودت حرف زدن. «چرا مردم به نظرهای آنلاین اعتماد می‌کنند؟» درباره‌ی آدم‌ها به‌طور کلی است، نه فقط خریدهای خودت."}],"example":{"text":"Q: \"Should parents always tell their children the truth?\"","item":"Which answer has a view, a reason and an example?","answer":"Mostly, yes, because children copy what adults do. For instance, if a parent promises a treat and then forgets, the child learns that promises do not matter.","why":{"en":"View (mostly, yes), reason (children copy adults), example (the forgotten promise).","tr":"Görüş (çoğunlukla evet), neden (çocuklar yetişkinleri taklit eder), örnek (unutulan söz).","fa":"نظر (بیشتر وقت‌ها، بله)، دلیل (بچه‌ها از بزرگ‌ترها تقلید می‌کنند)، مثال (قولی که فراموش شد)."}}},{"id":"S2-exp-talk","ctx":["S2-experience","S2-exp-talk"],"title":{"en":"Conversations, news and information","tr":"Konuşmalar, haberler ve bilgi","fa":"گفتگو، خبر و اطلاعات"},"asks":{"en":"A card about something you heard, read or discussed: a claim you thought was false, a long discussion about news, an important conversation, a talk about spending money, a science programme.","tr":"Duyduğun, okuduğun ya da tartıştığın bir şey hakkında kart: yanlış olduğunu düşündüğün bir iddia, bir haber üzerine uzun bir tartışma, önemli bir konuşma, para harcama üzerine bir sohbet, bir bilim programı.","fa":"کارتی درباره‌ی چیزی که شنیدی، خواندی یا درباره‌اش بحث کردی: ادعایی که فکر می‌کردی غلط است، بحثی طولانی درباره‌ی یک خبر، گفتگویی مهم، صحبتی درباره‌ی خرج کردن پول، یک برنامه‌ی علمی."},"fields":["Describe a time you heard a claim you believed was false.","Describe a long conversation you had about a piece of news.","Describe an important discussion you had with a family member.","Describe a science programme you watched.","Describe a conversation about how to spend money."],"words":[{"a":"I heard","b":"I came across / someone told me","tr":"... duydum","fa":"شنیدم"},{"a":"it was not true","b":"it turned out to be false","tr":"yanlış çıktı","fa":"معلوم شد درست نیست"},{"a":"I checked","b":"I looked it up / I double-checked","tr":"kontrol ettim","fa":"چکش کردم"},{"a":"we talked","b":"we had a long discussion about","tr":"uzun uzun konuştuk","fa":"مفصل درباره‌اش حرف زدیم"},{"a":"we didn't agree","b":"we saw it differently","tr":"farklı düşünüyorduk","fa":"نظرمان فرق داشت"},{"a":"he said","b":"he argued that / he pointed out that","tr":"... olduğunu savundu","fa":"استدلال کرد که"},{"a":"in the end","b":"eventually we agreed that","tr":"sonunda ... konusunda anlaştık","fa":"آخرش توافق کردیم که"},{"a":"surprised","b":"I couldn't believe that","tr":"inanamadım","fa":"باورم نمی‌شد"},{"a":"I learned","b":"it opened my eyes to","tr":"gözlerimi ... açtı","fa":"چشمم را به ... باز کرد"},{"a":"serious","b":"an important decision","tr":"önemli bir karar","fa":"تصمیمی مهم"},{"a":"the news","b":"a news story / an article","tr":"bir haber","fa":"یک خبر"},{"a":"online","b":"on social media","tr":"sosyal medyada","fa":"در شبکه‌های اجتماعی"}],"traps":[{"en":"Reporting speech: \"he said that it was...\" (past). Do not act out the whole dialogue.","tr":"Aktarma: \"he said that it was...\" (geçmiş). Bütün diyaloğu canlandırma.","fa":"نقل قول غیرمستقیم: «he said that it was...» (گذشته). کل گفتگو را بازی نکن."},{"en":"The card asks about a conversation, not the topic in general: keep the people and the moment in your talk.","tr":"Kart genel olarak konuyu değil, bir konuşmayı sorar: konuşmadaki kişileri ve anı koru.","fa":"کارت درباره‌ی یک گفتگوست، نه کل موضوع: آدم‌ها و آن لحظه را در صحبتت نگه دار."}],"example":{"lines":[["Candidate","A few months ago my uncle told me that drinking coffee makes you shorter."],["Candidate","He said that he had read it in a magazine, so he was completely sure."],["Candidate","I looked it up that evening, and it turned out to be a very old myth."]],"item":"How is the uncle’s claim reported?","answer":"With reported speech: \"told me that...\", \"he said that he had read it\".","why":{"en":"Reported speech keeps the story in the past and moves faster than a dialogue.","tr":"Dolaylı anlatım hikâyeyi geçmişte tutar ve diyalogdan daha hızlı ilerler.","fa":"نقل قول غیرمستقیم داستان را در گذشته نگه می‌دارد و از گفتگوی کامل سریع‌تر جلو می‌رود."}},"ideas":["where and when the conversation happened","who said what (reported speech)","what you thought at the time","what happened next","why you still remember it (explain)"],"general":true,"patterns":["S2-experience"],"often":{"pattern":"S2-experience","n":17,"of":40,"label":{"en":"Comes up often in the real exam: 17 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 17’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۷ آزمون از ۴۰ آزمونِ اخیر"}}},{"id":"S3-consumer","ctx":["S3-consumer"],"title":{"en":"Consumers, money and advertising","tr":"Tüketiciler, para ve reklam","fa":"مصرف‌کننده، پول و تبلیغات"},"asks":{"en":"General questions linked to the Part 2 card, about advertising, reviews, luxury, wealth, impulse buying and celebrities. The examiner wants an opinion, a reason, an example and, when it helps, the other side.","tr":"Part 2 kartına bağlı, reklam, yorumlar, lüks, zenginlik, dürtüsel alışveriş ve ünlüler hakkında genel sorular. Sınav görevlisi bir görüş, bir neden, bir örnek ve gerektiğinde karşı tarafı ister.","fa":"سؤال‌های کلی مرتبط با کارت Part 2، درباره‌ی تبلیغات، نقدها، تجمل، ثروت، خرید هیجانی و افراد مشهور. ممتحن یک نظر، یک دلیل، یک مثال و هرجا لازم بود طرف مقابل را می‌خواهد."},"fields":["Should advertising be more honest?","Why do people buy things they do not need?","Do online reviews help shoppers?","Should celebrities advertise products?","Does money make people happy?"],"words":[{"a":"adverts lie","b":"advertising can be misleading","tr":"reklam yanıltıcı olabilir","fa":"تبلیغ ممکن است گمراه‌کننده باشد"},{"a":"buy without thinking","b":"impulse buying","tr":"dürtüsel alışveriş","fa":"خرید هیجانی"},{"a":"famous people","b":"celebrities / influencers","tr":"ünlüler","fa":"آدم‌های مشهور"},{"a":"rich","b":"wealthy / well off","tr":"varlıklı","fa":"ثروتمند"},{"a":"expensive things","b":"luxury goods","tr":"lüks ürünler","fa":"کالاهای لوکس"},{"a":"people want it","b":"there is huge demand for","tr":"büyük talep var","fa":"تقاضای زیادی هست"},{"a":"the law should stop it","b":"it should be regulated","tr":"düzenlenmeli","fa":"باید قانون‌گذاری شود"},{"a":"young people copy","b":"young people are easily influenced","tr":"gençler kolay etkilenir","fa":"جوان‌ها زود تحت تأثیر قرار می‌گیرند"},{"a":"it depends","b":"it depends on the situation","tr":"duruma bağlı","fa":"بستگی به شرایط دارد"},{"a":"on the other hand","b":"then again / that said","tr":"öte yandan","fa":"از طرف دیگر"},{"a":"in my experience","b":"from what I've seen","tr":"gördüğüm kadarıyla","fa":"تا جایی که دیده‌ام"},{"a":"in the long run","b":"over time","tr":"uzun vadede","fa":"در درازمدت"}],"traps":[{"en":"Part 3 is about people in general, not only you. Move from \"I\" to \"people\", \"society\", \"young people\".","tr":"Part 3 yalnızca seninle değil, genel olarak insanlarla ilgilidir. \"Ben\"den \"insanlar\", \"toplum\", \"gençler\"e geç.","fa":"Part 3 درباره‌ی آدم‌ها به‌طور کلی است، نه فقط تو. از «من» به «مردم»، «جامعه»، «جوان‌ها» برو."},{"en":"A one-sentence opinion is too short. Give the reason and an example before you stop.","tr":"Tek cümlelik görüş çok kısadır. Durmadan önce nedeni ve bir örneği ver.","fa":"نظر یک‌جمله‌ای خیلی کوتاه است. قبل از تمام کردن، دلیل و یک مثال بیاور."}],"example":{"lines":[["Examiner","Why do people buy things they don’t really need?"],["Candidate","I think mainly because shopping has become a kind of entertainment."],["Candidate","For example, many people scroll through shopping apps when they’re bored, and buy something just to feel better."],["Candidate","That said, some of it is simply clever advertising."]],"item":"Which moves does the answer make?","answer":"Opinion, reason, a specific example, then the other side (\"That said...\").","why":{"en":"Four short moves make a full Part 3 answer of about thirty seconds.","tr":"Dört kısa hamle yaklaşık otuz saniyelik tam bir Part 3 cevabı oluşturur.","fa":"چهار حرکت کوتاه یک جواب کامل Part 3 حدود سی‌ثانیه‌ای می‌سازد."}},"ideas":["adverts give useful information but create needs","reviews help, but some are fake","happiness needs enough money, not unlimited money","celebrity adverts influence teenagers most"],"general":true,"patterns":["S3-consumer"],"often":{"pattern":"S3-consumer","n":8,"of":40,"label":{"en":"Comes up often in the real exam: 8 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 8’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۸ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Three parts, one examiner","tr":"Üç kısım, bir sınav görevlisi","fa":"سه بخش، یک ممتحن"},"body":{"en":"Part 1 (4-5 minutes): questions about you and one everyday topic. Part 2 (3-4 minutes): one minute to prepare, then up to two minutes alone, then one short question. Part 3 (4-5 minutes): a discussion of general questions. The test is recorded.","tr":"Part 1 (4-5 dakika): seninle ve günlük bir konuyla ilgili sorular. Part 2 (3-4 dakika): bir dakika hazırlık, sonra iki dakikaya kadar tek başına konuşma, sonra kısa bir soru. Part 3 (4-5 dakika): genel soruların tartışması. Sınav kaydedilir.","fa":"Part 1 (۴ تا ۵ دقیقه): سؤال‌هایی درباره‌ی خودت و یک موضوع روزمره. Part 2 (۳ تا ۴ دقیقه): یک دقیقه آماده شدن، بعد تا دو دقیقه حرف زدن به‌تنهایی و بعد یک سؤال کوتاه. Part 3 (۴ تا ۵ دقیقه): بحث درباره‌ی سؤال‌های کلی. آزمون ضبط می‌شود."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"One move for each part","tr":"Her kısım için bir hamle","fa":"برای هر بخش یک حرکت"},"steps":[{"en":"Part 1: answer, then add one reason or detail. Two or three sentences.","tr":"Part 1: cevap ver, sonra bir neden ya da ayrıntı ekle. İki üç cümle.","fa":"Part 1: جواب بده، بعد یک دلیل یا جزئیات اضافه کن. دو سه جمله."},{"en":"Part 2: write one key word for each line of the card, tell the story in order, and spend the last minute on the \"explain\" line.","tr":"Part 2: kartın her satırı için bir anahtar kelime yaz, hikâyeyi sırayla anlat ve son dakikayı \"explain\" satırına ayır.","fa":"Part 2: برای هر خط کارت یک کلیدواژه بنویس، داستان را به ترتیب تعریف کن و دقیقه‌ی آخر را به خط «explain» بده."},{"en":"Part 3: give a view, a reason and an example, then the other side if it helps.","tr":"Part 3: bir görüş, bir neden ve bir örnek ver; gerekiyorsa karşı tarafı da söyle.","fa":"Part 3: یک نظر، یک دلیل و یک مثال بده و اگر کمک می‌کند طرف مقابل را هم بگو."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Too short, or not about the question","tr":"Çok kısa ya da soruyla ilgisiz","fa":"خیلی کوتاه، یا بی‌ربط به سؤال"},"body":{"en":"The most common problem is answers that are too short. In Part 3, the second is answering about yourself when the question is about people in general. Listen to the question word: why, how, should.","tr":"En yaygın sorun çok kısa cevaplardır. Part 3’te ikincisi, soru genel olarak insanlarla ilgiliyken kendinden söz etmektir. Soru kelimesine kulak ver: why, how, should.","fa":"رایج‌ترین مشکل جواب‌های خیلی کوتاه است. در Part 3 مشکل دوم این است که وقتی سؤال درباره‌ی آدم‌ها به‌طور کلی است، درباره‌ی خودت جواب بدهی. به کلمه‌ی پرسشی گوش بده: why، how، should."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Planning a Part 2 talk in one minute","tr":"Bir dakikada Part 2 konuşması planlamak","fa":"برنامه‌ریزی صحبت Part 2 در یک دقیقه"},"instruction":"Card: Describe a time when you lost something important. You should say: what you lost; where you lost it; what you did; and explain how you felt.","item":"Write one key word for each line.","answer":"wallet · train · called station + bank · panic → relief (returned)","walk":[{"en":"One or two words per line, not sentences: you will speak, not read.","tr":"Her satır için bir iki kelime, cümle değil: okumayacak, konuşacaksın.","fa":"برای هر خط یکی دو کلمه، نه جمله: قرار است حرف بزنی، نه از رو بخوانی."},{"en":"Add one detail that gives the story life: who returned it, or a surprise.","tr":"Hikâyeye canlılık katan bir ayrıntı ekle: onu kim geri getirdi ya da bir sürpriz.","fa":"یک جزئیات اضافه کن که به داستان جان بدهد: چه کسی پسش آورد یا یک غافلگیری."},{"en":"Note the feeling for the last line: it gives you the final minute.","tr":"Son satır için duyguyu not et: son dakikayı o doldurur.","fa":"احساس را برای خط آخر یادداشت کن: دقیقه‌ی آخر را همین پر می‌کند."}]},"quick":{"prompt":"Part 3: \"Why do people trust online reviews?\" Which answer is about people in general?","options":["I read reviews before I buy shoes.","Yes, I do.","Many people trust them because they come from ordinary customers rather than from the company."],"correct":2,"why":{"en":"It talks about people in general and gives a reason; the others are about the speaker only or too short.","tr":"Genel olarak insanlardan söz ediyor ve bir neden veriyor; diğerleri yalnızca konuşanla ilgili ya da çok kısa.","fa":"درباره‌ی آدم‌ها به‌طور کلی حرف می‌زند و دلیل می‌آورد؛ بقیه فقط درباره‌ی گوینده‌اند یا خیلی کوتاه‌اند."}},"remember":{"en":"Part 1: answer plus a detail. Part 2: key words, then a story in order. Part 3: view, reason, example.","tr":"Part 1: cevap artı bir ayrıntı. Part 2: anahtar kelimeler, sonra sıralı bir hikâye. Part 3: görüş, neden, örnek.","fa":"Part 1: جواب به‌اضافه‌ی یک جزئیات. Part 2: کلیدواژه‌ها، بعد داستانی به ترتیب. Part 3: نظر، دلیل، مثال."},"type":"explain","id":"c-x02-s-e","course":"ielts-exams","exam":"exam-02","unit":"x02-s"},"sets":{"title":{"en":"The Speaking test","tr":"Speaking sınavı","fa":"آزمون Speaking"},"note":{"en":"Do the three parts in order, without a break, as in the real test. Record yourself if you can, then use the self-check under each part.","tr":"Gerçek sınavdaki gibi üç kısmı sırayla ve ara vermeden yap. Yapabilirsen kendini kaydet, sonra her kısmın altındaki öz değerlendirmeyi kullan.","fa":"سه بخش را به ترتیب و بدون مکث انجام بده، مثل آزمون واقعی. اگر می‌توانی صدایت را ضبط کن و بعد از خودارزیابیِ زیر هر بخش استفاده کن."},"sequential":true,"examinerVoice":{"accent":"British (standard Southern)","gender":"M","tts":{"engine":"kokoro","voice":"bm_fable"},"role":"Examiner"},"sets":[{"part":"Part 1","ctx":["S1-frame","S1-places"],"minutes":[4,5],"title":{"en":"Part 1: about you, then your neighbourhood","tr":"Part 1: senin hakkında, sonra mahallen","fa":"Part 1: درباره‌ی خودت، بعد محله‌ات"},"examinerIntro":["Good afternoon. My name is Thomas Reid. Can you tell me your full name, please?","Thank you. And can I see your identification, please?","Thank you. Now, in this first part, I’d like to ask you some questions about yourself."],"frame":["Do you work or are you a student?","Why did you choose that job or that subject?","Let’s talk about your home. How long have you lived there?"],"topicIntro":"Now let’s talk about your neighbourhood.","questions":["What do you like most about the area where you live?","Do you know many of your neighbours? [Why/Why not?]","Has your neighbourhood changed much in recent years?","Is there anything you would like to change about your area?"],"model":"Q: What do you like most about the area where you live?\nA: Probably how convenient it is. I can walk to the supermarket, the gym and the metro station in under ten minutes, so I hardly ever need the car.\n\nQ: Do you know many of your neighbours?\nA: Only a few, to be honest. I live in a big block of flats, and people come and go a lot. But I get on well with the family next door; we look after each other’s plants when someone is away.\n\nQ: Has your neighbourhood changed much in recent years?\nA: Quite a lot. When I moved there, it was mainly offices, but several have been turned into flats, so it’s much livelier in the evenings now.\n\nQ: Is there anything you would like to change about your area?\nA: I’d like more trees. The streets are quite grey, and in summer they get really hot, so a bit more green would make a big difference.","moves":[{"label":{"en":"Answer first","tr":"Önce cevap","fa":"اول جواب"},"example":"Probably how convenient it is."},{"label":{"en":"Add a reason or a detail","tr":"Bir neden ya da ayrıntı ekle","fa":"یک دلیل یا جزئیات اضافه کن"},"example":"I can walk to the supermarket, the gym and the metro station in under ten minutes."},{"label":{"en":"A small then/now or a contrast","tr":"Küçük bir o zaman/şimdi ya da karşıtlık","fa":"یک «آن موقع/حالا» یا تضاد کوچک"},"example":"When I moved there, it was mainly offices... so it’s much livelier in the evenings now."}],"selfCheck":[{"en":"I answered every question with two or three sentences, not one word.","tr":"Her soruyu tek kelimeyle değil, iki üç cümleyle cevapladım.","fa":"به هر سؤال با دو سه جمله جواب دادم، نه یک کلمه."},{"en":"I gave a concrete detail about my own area each time.","tr":"Her seferinde kendi bölgemle ilgili somut bir ayrıntı verdim.","fa":"هر بار یک جزئیات مشخص از محله‌ی خودم گفتم."},{"en":"I used the present perfect for changes (\"has changed\", \"have been turned into\").","tr":"Değişiklikler için present perfect kullandım (\"has changed\", \"have been turned into\").","fa":"برای تغییرها از حال کامل استفاده کردم («has changed»، «have been turned into»)."}]},{"part":"Part 2","ctx":["S2-experience"],"minutes":[3,4],"title":{"en":"Part 2: advice that turned out to be wrong","tr":"Part 2: sonradan yanlış çıkan bir tavsiye","fa":"Part 2: توصیه‌ای که بعداً غلط از آب درآمد"},"examinerIntro":["Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. Before you talk, you’ll have one minute to think about what you’re going to say. You can make some notes if you wish. Do you understand?","Here’s some paper and a pencil for making notes, and here’s your topic. I’d like you to describe a time when someone gave you advice that turned out to be wrong.","All right? Remember you have one to two minutes for this. Don’t worry if I stop you. I’ll tell you when the time is up. Can you start speaking now, please?"],"card":{"task":"Describe a time when someone gave you advice that turned out to be wrong.","bullets":["who gave you the advice","what the advice was","what happened when you followed it","and explain how you felt about it"]},"prep":60,"talk":120,"roundingOff":["Do you usually ask other people for advice before you make a decision?"],"model":"I’d like to talk about some advice my older cousin gave me a few years ago, when I was buying my first car. He knows a lot about engines, or at least he says he does, so I trusted him completely.\n\nI had found two cars I liked: a newer one from a dealer and an older one that a private seller was offering for much less. My cousin told me to buy the older one. His argument was that dealers always charge too much, and that an older car would be cheaper to insure and easy to repair.\n\nSo I took his advice. For the first month everything was fine. Then, on a rainy evening on the motorway, the engine warning light came on and the car simply stopped. It turned out that the cambelt was worn out, and the repair cost almost half of what I had paid for the car. The dealer’s car, I found out later, came with a one-year guarantee that would have covered everything.\n\nAt the time, I felt really frustrated, mostly with myself rather than with him. He meant well, and he genuinely believed what he said. But I had not checked anything for myself: I hadn’t asked for the service history or paid for an inspection. Looking back, it was a useful lesson. Now, when someone gives me advice about something important, I listen, but I always double-check the facts before I spend any money.","moves":[{"label":{"en":"Start with who and when","tr":"Kim ve ne zaman ile başla","fa":"با «چه کسی» و «کی» شروع کن"},"example":"I’d like to talk about some advice my older cousin gave me a few years ago, when I was buying my first car."},{"label":{"en":"Tell the events in order, with a turning point","tr":"Olayları sırayla, bir dönüm noktasıyla anlat","fa":"اتفاق‌ها را به ترتیب و با یک نقطه‌ی عطف تعریف کن"},"example":"So I took his advice. For the first month everything was fine. Then, on a rainy evening... the car simply stopped."},{"label":{"en":"Spend time on the explain line","tr":"Açıklama satırına zaman ayır","fa":"روی خط توضیح وقت بگذار"},"example":"At the time, I felt really frustrated, mostly with myself... Looking back, it was a useful lesson."}],"selfCheck":[{"en":"I covered all four lines of the card and spoke for close to two minutes.","tr":"Kartın dört satırının hepsini ele aldım ve iki dakikaya yakın konuştum.","fa":"هر چهار خط کارت را گفتم و نزدیک دو دقیقه حرف زدم."},{"en":"I used \"it turned out that\" or \"I found out later\" for the moment the advice proved wrong.","tr":"Tavsiyenin yanlış çıktığı an için \"it turned out that\" ya da \"I found out later\" kullandım.","fa":"برای لحظه‌ای که معلوم شد توصیه غلط بوده از «it turned out that» یا «I found out later» استفاده کردم."},{"en":"I explained my feelings then and what I think now.","tr":"O zamanki duygularımı ve şimdi ne düşündüğümü açıkladım.","fa":"احساسم در آن موقع و فکرم در حال حاضر را توضیح دادم."}]},{"part":"Part 3","ctx":["S3-consumer","S3-education"],"minutes":[4,5],"title":{"en":"Part 3: honesty, trust and online reviews","tr":"Part 3: dürüstlük, güven ve çevrim içi yorumlar","fa":"Part 3: صداقت، اعتماد و نظرهای آنلاین"},"examinerIntro":["We’ve been talking about advice that turned out to be wrong, and I’d like to discuss with you one or two more general questions related to this."],"subtopics":[{"title":"Honesty and children","questions":["How do children learn to be honest?","Is it ever acceptable for parents to tell their children a white lie?","Do you think schools should teach children about honesty? Why?"]},{"title":"Trust and online reviews","questions":["Why do so many people trust reviews written by strangers online?","What problems can fake reviews cause for shoppers and for businesses?","Who should be responsible for checking that online reviews are genuine?"]}],"model":"Q: Why do so many people trust reviews written by strangers online?\nA: I think the main reason is that reviews feel independent. An advert is written by the company, so people expect it to exaggerate, whereas a review seems to come from an ordinary customer with nothing to gain. When you see hundreds of reviews saying the same thing, it’s natural to believe them. That said, people are becoming more careful, because they know some reviews are paid for.\n\nQ: Who should be responsible for checking that online reviews are genuine?\nA: Mainly the websites that publish them, in my view. They earn money from the traffic, so they have both the means and the duty to remove fake ones. In some countries, governments now fine companies that buy false reviews, and I think that’s fair. Shoppers can help too, by reading the negative reviews as well as the positive ones, but they shouldn’t have to do all the work.","moves":[{"label":{"en":"Give a clear view","tr":"Net bir görüş ver","fa":"نظرت را روشن بگو"},"example":"Mainly the websites that publish them, in my view."},{"label":{"en":"Support it: reason + example","tr":"Destekle: neden + örnek","fa":"پشتیبانی کن: دلیل + مثال"},"example":"They earn money from the traffic... In some countries, governments now fine companies that buy false reviews."},{"label":{"en":"Show the other side","tr":"Karşı tarafı göster","fa":"طرف مقابل را نشان بده"},"example":"Shoppers can help too... but they shouldn’t have to do all the work."}],"selfCheck":[{"en":"I gave a clear view in my first sentence.","tr":"İlk cümlemde net bir görüş verdim.","fa":"در جمله‌ی اولم نظر روشنی دادم."},{"en":"I supported it with a reason and a real example.","tr":"Onu bir neden ve gerçek bir örnekle destekledim.","fa":"آن را با یک دلیل و یک مثال واقعی پشتیبانی کردم."},{"en":"I talked about people and society in general, not only about myself.","tr":"Yalnızca kendimden değil, genel olarak insanlardan ve toplumdan söz ettim.","fa":"درباره‌ی آدم‌ها و جامعه به‌طور کلی حرف زدم، نه فقط خودم."}]}],"type":"sets","id":"c-x02-s-p","course":"ielts-exams","exam":"exam-02","unit":"x02-s"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"My area is very lively.\" Lively means...","options":["quiet and empty","busy, with a lot going on","old-fashioned"],"correct":1,"why":{"en":"Lively = full of activity and people.","tr":"Lively = hareketli, insan ve etkinlik dolu.","fa":"lively یعنی پر از جنب‌وجوش و آدم."}},{"tests":"paraphrase","point":2,"prompt":"Which phrase means \"later I discovered that\"?","options":["it turned out that","I hoped that","I explained that"],"correct":0,"why":{"en":"\"It turned out that\" introduces a fact you learned afterwards.","tr":"\"It turned out that\", sonradan öğrendiğin bir gerçeği getirir.","fa":"«it turned out that» واقعیتی را می‌آورد که بعداً فهمیدی."}},{"tests":"method","point":2,"prompt":"You have one minute before your Part 2 talk. What is the best use of it?","options":["Write the whole talk in full sentences","Wait quietly","Write one key word for each line of the card"],"correct":2,"why":{"en":"Key words keep you on track; full sentences take too long and make you read aloud.","tr":"Anahtar kelimeler yolda kalmanı sağlar; tam cümleler çok uzun sürer ve sesli okumana yol açar.","fa":"کلیدواژه‌ها تو را در مسیر نگه می‌دارند؛ جمله‌ی کامل خیلی وقت می‌گیرد و باعث می‌شود از رو بخوانی."}},{"tests":"trap","point":3,"prompt":"Part 3: \"Should websites remove fake reviews?\" Which answer has the most complete structure?","options":["Yes.","Yes, because they profit from the reviews; some countries already fine firms that buy them, although checking every review is hard.","I once bought a bad lamp because of a review."],"correct":1,"why":{"en":"A view, a reason, an example and the other side; the last answer is only about the speaker.","tr":"Bir görüş, bir neden, bir örnek ve karşı taraf; son cevap yalnızca konuşanla ilgili.","fa":"یک نظر، یک دلیل، یک مثال و طرف مقابل؛ جواب آخر فقط درباره‌ی گوینده است."}},{"tests":"trap","point":1,"prompt":"Part 1: \"Do you know many of your neighbours?\" Which answer is the right length?","options":["Not many, to be honest. People in my building change often, but I know the family next door well.","No.","Neighbours are important in every society because communities need trust, and in history..."],"correct":0,"why":{"en":"Part 1 wants a short, natural answer with one detail, not one word and not a speech.","tr":"Part 1 tek kelime ya da bir nutuk değil, bir ayrıntıyla kısa ve doğal bir cevap ister.","fa":"Part 1 جوابی کوتاه و طبیعی با یک جزئیات می‌خواهد، نه یک کلمه و نه سخنرانی."}}],"id":"c-x02-s-x","course":"ielts-exams","exam":"exam-02","unit":"x02-s"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
